-- ============================================================================
-- V24__create_field_preset.sql
-- US10.6: пресеты полей шаблона. US10.7.3: пресеты несут и правило маркировки.
--
-- Пресет — именованный набор определений полей И правило маркировки,
-- который применяется к DRAFT-версии шаблона кнопкой «Применить пресет».
-- Форматы полей и правила совпадают с product_template_version,
-- поэтому пресет применяется без конвертаций.
--
-- Системные пресеты (is_system = TRUE) нельзя изменить или удалить.
-- ============================================================================

CREATE TABLE IF NOT EXISTS field_preset
(
    id                BIGSERIAL PRIMARY KEY,
    name              VARCHAR(200) NOT NULL,
    description       VARCHAR(500),
    fields_json       JSONB        NOT NULL DEFAULT '[]'::jsonb,
    marking_rule_json JSONB        NOT NULL DEFAULT '{"sequence":[]}'::jsonb,
    is_system         BOOLEAN      NOT NULL DEFAULT FALSE,
    created_at        TIMESTAMP    NOT NULL DEFAULT NOW(),
    created_by        VARCHAR(100)
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_field_preset_name_unique
    ON field_preset (LOWER(name));

COMMENT ON TABLE field_preset IS 'Пресеты шаблона: поля + правило маркировки для типовых изделий';
COMMENT ON COLUMN field_preset.fields_json IS 'Массив FieldDefinition в формате product_template_version.fields_json';
COMMENT ON COLUMN field_preset.marking_rule_json IS 'Правило маркировки в формате product_template_version.marking_rule_json';
COMMENT ON COLUMN field_preset.is_system IS 'Системный пресет: нельзя изменить или удалить';

-- ============================================================================
-- Системные пресеты (по документам «Карточки»)
-- ============================================================================
INSERT INTO field_preset (name, description, fields_json, marking_rule_json, is_system, created_at, created_by)
